-- Privacy Policy and Terms of Service as CMS pages.
--
-- The driver and rider settings screens carried "Privacy Policy" and "Terms of
-- Service" rows that were buttons with no handler. They now open these pages.
-- Seeding them in the CMS rather than hardcoding the text in the app means Ops
-- can revise a policy without a deploy — a privacy notice nobody can correct in
-- a hurry is worse than none.
--
-- BOTH DOCUMENTS ARE DRAFTS AND HAVE NOT BEEN REVIEWED BY A LAWYER. They
-- describe the platform's real behaviour and real data practices, and each ends
-- with a section saying plainly that it awaits legal review. They must be
-- reviewed and approved by counsel — and checked against the Nigeria Data
-- Protection Act — before launch. Editing them in the content console replaces
-- this seed; the seed only guarantees the screens are not empty.
--
-- Dollar-quoted rather than single-quoted: the prose contains apostrophes.

INSERT INTO "cms_contents" ("id", "type", "slug", "title", "body", "status", "version", "published_at", "created_at", "updated_at")
VALUES
  (
    gen_random_uuid(), 'STATIC_PAGE', 'privacy-policy', 'Privacy Policy',
    $json${"sections": [{"heading": "About this notice", "body": "This notice explains what personal information DrippleX collects when you use the DrippleX app as a customer, driver, rider or merchant, why we collect it, who we share it with, and the choices you have.\n\nDrippleX operates ride-hailing, marketplace ordering and delivery services in Nigeria. Where this notice says “we” or “DrippleX”, it means the DrippleX entity that provides those services to you."}, {"heading": "What we collect", "body": "Account details you give us: your name, phone number, and email address if you choose to add one. We do not use usernames — your phone number is your identity on DrippleX.\n\nVerification details, if you sign up as a driver, rider or merchant: identity and vehicle documents, photographs of those documents, and the outcome of any inspection or background check.\n\nLocation: your device location while you are using a service that needs it — booking or taking a trip, or making or delivering an order. Drivers and riders share location while they are online so we can offer them nearby work and so a customer can watch their trip or delivery arrive.\n\nTransactions: what you ordered or where you travelled, the fare or price, how you paid, and your DrippleX wallet balance and history.\n\nDevice and usage information: the device you use, app version, and how you move through the app, so we can find and fix faults.\n\nCommunications: messages you send through in-app chat, and support requests you raise with us."}, {"heading": "Why we use it", "body": "To provide the service — to match a passenger with a driver, an order with a merchant and a rider, to price a trip, and to take payment.\n\nTo keep people safe — to verify that a driver is who they say they are, that a vehicle has passed inspection, and to investigate an incident or a complaint.\n\nTo meet legal and regulatory obligations, including record-keeping and responding to lawful requests from authorities.\n\nTo improve the service — to understand where the app is failing people and to fix it."}, {"heading": "Who we share it with", "body": "Drivers and riders see a customer first name, pickup and drop-off points, and the trip or order details they need to complete the job. They do not see a customer phone number.\n\nCustomers see the assigned driver or rider name and vehicle details.\n\nMerchants see the order and the customer delivery address.\n\nPayment providers process card and transfer payments; DrippleX does not store your full card details.\n\nService providers who host our systems and send our messages, under contract and only for those purposes.\n\nAuthorities and regulators, where the law requires it.\n\nWe do not sell your personal information."}, {"heading": "How long we keep it", "body": "Account and transaction records are kept for as long as your account is open and afterwards for as long as the law requires us to keep financial and safety records. Verification documents are kept for the life of the account and a period afterwards, so a past decision can be explained. Location traces attached to a completed trip are kept with that trip record."}, {"heading": "Your choices", "body": "You can review and correct your profile details in the app.\n\nYou can turn off location sharing in your device settings — but a ride, an order or a delivery cannot be completed without it, so those services will not work.\n\nYou can ask us for a copy of the personal information we hold about you, or ask us to correct or delete it. Some records we must keep by law and cannot delete on request; where that applies, we will tell you.\n\nYou can close your account by contacting support."}, {"heading": "Security", "body": "We protect your information with access controls, encryption in transit, and audit logs on sensitive actions. No system is perfect; if a breach ever affects your personal information, we will tell you and the relevant authority as the law requires."}, {"heading": "Contact us", "body": "Questions about this notice, or about the information we hold on you, can be sent to DrippleX support on WhatsApp at +2349061616116."}, {"heading": "Changes", "body": "We will update this notice when our practices change. The date at the top of this page is when it was last revised. Material changes will be notified in the app."}, {"heading": "⚠️ Draft pending legal review", "body": "This document was drafted for DrippleX and has NOT yet been reviewed by a qualified lawyer. It describes the platform actual data practices as built, but it is not legal advice and must be reviewed and approved by counsel — and checked against the Nigeria Data Protection Act — before DrippleX relies on it publicly. Ops can revise this text in the content console without a deploy."}]}$json$::jsonb,
    'PUBLISHED', 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
  ),
  (
    gen_random_uuid(), 'STATIC_PAGE', 'terms-of-service', 'Terms of Service',
    $json${"sections": [{"heading": "Agreement to these terms", "body": "These terms govern your use of the DrippleX app and services. By creating an account or using DrippleX you agree to them. If you do not agree, do not use the service.\n\nDrippleX provides ride-hailing, marketplace ordering and delivery in Nigeria."}, {"heading": "Your account", "body": "You must be at least 18 years old to hold a DrippleX account.\n\nYour phone number identifies your account. Keep your account and any PIN you set to yourself — DrippleX staff will never ask you for your PIN. You are responsible for activity on your account.\n\nGive us accurate information and keep it current. We may suspend or close an account where the information given is false."}, {"heading": "What DrippleX is, and is not", "body": "DrippleX connects customers with independent drivers, riders and merchants. Drivers and riders are not employees of DrippleX. Merchants sell their own goods on their own terms.\n\nDrippleX is responsible for operating the platform fairly: matching, pricing as published, taking payment correctly, and handling disputes. It is not the provider of the transport or the goods themselves."}, {"heading": "Fares, prices and payment", "body": "Trip fares are calculated from a base fare plus distance and time at the rates published in the app, subject to a minimum fare per trip. Some areas may carry a surcharge, which is shown before you book and itemised on your receipt.\n\nMarketplace prices are set by the merchant. Delivery fees and taxes are shown before you confirm an order.\n\nYou may pay by DrippleX wallet, card, bank transfer or cash where offered. Payment is due on completion. Where a payment fails, we may recover the amount from your DrippleX wallet or block further bookings until it is settled."}, {"heading": "Cancellations and refunds", "body": "You may cancel a trip before it starts. A merchant may reject an order it cannot fulfil, and a full refund follows.\n\nWhere something goes wrong — an order not delivered, a trip not provided, a payment taken twice — raise it through the app. We investigate and refund where the complaint is upheld. Refunds return to the original payment method or to your DrippleX wallet."}, {"heading": "Conduct", "body": "Treat drivers, riders, merchants and other customers with respect. Do not use DrippleX to carry anything illegal, to harass anyone, to defraud the platform, or to interfere with how it works.\n\nWe may suspend or close an account that breaks these rules, and we will tell you why."}, {"heading": "For drivers, riders and merchants", "body": "You must hold and maintain the licences, permits, insurance and vehicle standards the law requires for the work you do, and provide proof when we ask.\n\nYou must complete the verification and inspection steps before going online, and keep them current.\n\nDrippleX charges a commission on completed work at the rate published in your app. Earnings are paid to your DrippleX wallet and can be withdrawn to your bank account subject to the payout schedule and your PIN.\n\nYou choose when to work. You are not obliged to accept any particular job."}, {"heading": "Safety", "body": "Do not use the app while driving. Report any incident, accident or safety concern through the in-app SOS or to support immediately.\n\nWe may share your information with emergency services or authorities where there is a risk to someone safety."}, {"heading": "Liability", "body": "DrippleX is liable for failures of the platform itself. It is not liable for the conduct of an independent driver, rider, merchant or customer, or for goods sold by a merchant, beyond what the law requires of an intermediary.\n\nNothing in these terms limits liability for death or personal injury caused by negligence, for fraud, or for anything else that cannot be limited under Nigerian law."}, {"heading": "Changes to these terms", "body": "We may change these terms. The date at the top of this page is when they were last revised, and material changes will be notified in the app. Continuing to use DrippleX after a change means you accept it."}, {"heading": "Governing law and disputes", "body": "These terms are governed by the laws of the Federal Republic of Nigeria.\n\nIf you have a complaint, contact DrippleX support first — most disputes are resolved there. Anything unresolved may be taken to the courts of Nigeria."}, {"heading": "Contact", "body": "DrippleX support is on WhatsApp at +2349061616116."}, {"heading": "⚠️ Draft pending legal review", "body": "This document was drafted for DrippleX and has NOT yet been reviewed by a qualified lawyer. It reflects how the platform actually behaves — commission, minimum fare, surcharges, cash and wallet payment, driver verification — but it is not legal advice and must be reviewed and approved by counsel before DrippleX relies on it. Ops can revise this text in the content console without a deploy."}]}$json$::jsonb,
    'PUBLISHED', 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
  )
ON CONFLICT ("slug") DO NOTHING;
